-- Budget module (budget.db)
-- Plans, allocations, requests, commitments and expenditure.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE budget_plans (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        plan_name TEXT NOT NULL,
        fiscal_year INTEGER NOT NULL,
        description TEXT NOT NULL DEFAULT '',
        total_budget NUMERIC NOT NULL CHECK (total_budget >= 0),
        currency TEXT NOT NULL DEFAULT 'ETB'
            CHECK (currency IN ('ETB', 'USD', 'EUR', 'GBP')),
        status TEXT NOT NULL DEFAULT 'Draft'
            CHECK (status IN ('Draft', 'Approved', 'Active', 'Closed')),
        created_by INTEGER,
        created_by_name TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    , updated_by INTEGER, updated_by_name TEXT);

CREATE TABLE budget_allocations (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        plan_id INTEGER NOT NULL,
        allocation_name TEXT NOT NULL,
        department TEXT NOT NULL DEFAULT 'general',
        currency TEXT NOT NULL DEFAULT 'ETB'
            CHECK (currency IN ('ETB', 'USD', 'EUR', 'GBP')),
        allocated_amount NUMERIC NOT NULL CHECK (allocated_amount >= 0),
        status TEXT NOT NULL DEFAULT 'Active'
            CHECK (status IN ('Active', 'Closed')),
        notes TEXT NOT NULL DEFAULT '',
        created_by INTEGER,
        created_by_name TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, department_id INTEGER , updated_by INTEGER, updated_by_name TEXT,
        FOREIGN KEY (plan_id) REFERENCES budget_plans(id)
    );

CREATE TABLE budget_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        request_title TEXT NOT NULL,
        department TEXT NOT NULL,
        justification TEXT NOT NULL DEFAULT '',
        requested_amount NUMERIC NOT NULL CHECK (requested_amount > 0),
        currency TEXT NOT NULL DEFAULT 'ETB'
            CHECK (currency IN ('ETB', 'USD', 'EUR', 'GBP')),
        status TEXT NOT NULL DEFAULT 'Pending'
            CHECK (status IN ('Pending', 'Approved', 'Rejected')),
        plan_id INTEGER,
        requested_by INTEGER,
        requested_by_name TEXT NOT NULL DEFAULT '',
        review_comment TEXT NOT NULL DEFAULT '',
        reviewed_by TEXT NOT NULL DEFAULT '',
        reviewed_at TEXT,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, department_id INTEGER , updated_by INTEGER, updated_by_name TEXT, updated_at TEXT,
        FOREIGN KEY (plan_id) REFERENCES budget_plans(id)
    );

CREATE TABLE budget_approvals (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        request_id INTEGER NOT NULL,
        approver_id INTEGER,
        approver_name TEXT NOT NULL DEFAULT '',
        decision TEXT NOT NULL,
        comment TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (request_id) REFERENCES budget_requests(id)
            ON DELETE CASCADE
    );

CREATE TABLE budget_commitments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        allocation_id INTEGER NOT NULL,
        source_table TEXT NOT NULL,
        source_id INTEGER NOT NULL,
        amount NUMERIC NOT NULL CHECK (amount >= 0),
        currency TEXT NOT NULL DEFAULT 'ETB',
        status TEXT NOT NULL DEFAULT 'Open'
            CHECK (status IN ('Open', 'Released', 'Converted')),
        description TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        UNIQUE (source_table, source_id),
        FOREIGN KEY (allocation_id) REFERENCES budget_allocations(id)
    );

CREATE TABLE "budget_expenditures" (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        allocation_id INTEGER NOT NULL,
        description TEXT NOT NULL,
        amount NUMERIC NOT NULL CHECK (amount > 0),
        currency TEXT NOT NULL DEFAULT 'ETB'
            CHECK (currency IN ('ETB', 'USD', 'EUR', 'GBP')),
        reference TEXT NOT NULL DEFAULT '',
        recorded_by INTEGER,
        recorded_by_name TEXT NOT NULL DEFAULT '',
        procurement_order_id INTEGER,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        finance_invoice_id INTEGER,
        finance_transaction_id INTEGER, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT,
        FOREIGN KEY (allocation_id) REFERENCES budget_allocations(id)
    );

CREATE INDEX idx_budget_alloc_department ON budget_allocations(department);
CREATE INDEX idx_budget_alloc_department_id ON budget_allocations(department_id);
CREATE INDEX idx_budget_alloc_plan ON budget_allocations(plan_id);
CREATE INDEX idx_budget_req_department_id ON budget_requests(department_id);
CREATE INDEX idx_budget_req_requester ON budget_requests(requested_by);
CREATE INDEX idx_budget_req_status
                ON budget_requests(status, created_at);
CREATE INDEX idx_budget_commitment_alloc ON budget_commitments(allocation_id, status);
CREATE INDEX idx_budget_exp_finance_invoice ON budget_expenditures(finance_invoice_id);
CREATE INDEX idx_budget_exp_finance_tx ON budget_expenditures(finance_transaction_id);
CREATE INDEX idx_budget_exp_recorder ON budget_expenditures(recorded_by);
CREATE INDEX idx_budget_expenditure_alloc ON budget_expenditures(allocation_id);
